--
-- TABLES
--
--
-- Table 'account' generated from model 'Account'
-- User account model containing properties related to a user&#39;s account.
--
CREATE TABLE IF NOT EXISTS account (
    about TEXT DEFAULT NULL,
    account_type TEXT DEFAULT NULL,
    board_count INTEGER DEFAULT NULL,
    business_name TEXT DEFAULT NULL,
    follower_count INTEGER DEFAULT NULL,
    following_count INTEGER DEFAULT NULL,
    "id" TEXT DEFAULT NULL,
    monthly_views INTEGER DEFAULT NULL,
    pin_count INTEGER DEFAULT NULL,
    profile_image TEXT DEFAULT NULL,
    username TEXT DEFAULT NULL,
    website_url TEXT DEFAULT NULL
);
COMMENT ON TABLE account IS 'User account model containing properties related to a user&#39;s account.. Original model name - Account.';
COMMENT ON COLUMN account.about IS 'Profile about description.';
COMMENT ON COLUMN account.account_type IS 'Type of account';
COMMENT ON COLUMN account.board_count IS '  User account board count.   **Note**: Board count on user account level may differ from counts found elsewhere due to attribution of collaborative Boards.';
COMMENT ON COLUMN account.follower_count IS 'User account follower count.';
COMMENT ON COLUMN account.following_count IS 'User account following count.';
COMMENT ON COLUMN account."id" IS 'User account ID.';
COMMENT ON COLUMN account.monthly_views IS 'User account monthly views.';
COMMENT ON COLUMN account.pin_count IS 'User account pin count. This includes both created and saved pins.';

--
-- Table 'account_template' generated from model 'AccountTemplate'
--
CREATE TABLE IF NOT EXISTS account_template (
    ad_account_id TEXT DEFAULT NULL,
    ad_account_ids JSON DEFAULT NULL,
    ade_columns JSON DEFAULT NULL,
    attribution_type TEXT DEFAULT NULL,
    click_window_days DECIMAL(20, 9) DEFAULT NULL,
    "columns" JSON DEFAULT NULL,
    conversion_report_time_type TEXT DEFAULT NULL,
    creation_source TEXT DEFAULT NULL,
    custom_column_ids JSON DEFAULT NULL,
    display_metadata TEXT DEFAULT NULL,
    engagement_window_days DECIMAL(20, 9) DEFAULT NULL,
    filters_json TEXT DEFAULT NULL,
    granularity TEXT DEFAULT NULL,
    "id" TEXT NOT NULL,
    ingestion_sources JSON DEFAULT NULL,
    is_default BOOLEAN DEFAULT NULL,
    is_deleted BOOLEAN DEFAULT NULL,
    is_owned_by_user BOOLEAN DEFAULT NULL,
    is_scheduled BOOLEAN DEFAULT NULL,
    "name" TEXT DEFAULT NULL,
    report_end_relative_days_in_past DECIMAL(20, 9) DEFAULT NULL,
    report_format TEXT DEFAULT NULL,
    report_level TEXT DEFAULT NULL,
    report_start_relative_days_in_past DECIMAL(20, 9) DEFAULT NULL,
    reporting_time_zone TEXT DEFAULT NULL,
    sort_by TEXT DEFAULT NULL,
    "type" TEXT DEFAULT NULL,
    updated_time DECIMAL(20, 9) DEFAULT NULL,
    user_id TEXT DEFAULT NULL,
    view_window_days DECIMAL(20, 9) DEFAULT NULL
);
COMMENT ON TABLE account_template IS 'Original model name - AccountTemplate.';
COMMENT ON COLUMN account_template.ad_account_id IS 'ID of the Ad Account that owns the template';
COMMENT ON COLUMN account_template.ad_account_ids IS 'IDs of the Ad Accounts that have access to this template';
COMMENT ON COLUMN account_template.ade_columns IS 'A list of ADE columns';
COMMENT ON COLUMN account_template.attribution_type IS 'Attribution type for Brand/Category/SKU reports';
COMMENT ON COLUMN account_template.click_window_days IS 'The length of the sliding window over which click conversions will be attributed';
COMMENT ON COLUMN account_template."columns" IS 'A list of columns to be included in the report';
COMMENT ON COLUMN account_template.conversion_report_time_type IS 'Conversion report time type';
COMMENT ON COLUMN account_template.creation_source IS 'The surface used to create this template';
COMMENT ON COLUMN account_template.custom_column_ids IS 'A list of custom column IDs';
COMMENT ON COLUMN account_template.display_metadata IS 'Additional metadata about this reporting template';
COMMENT ON COLUMN account_template.engagement_window_days IS 'The length of the sliding window over which engagement conversions will be attributed';
COMMENT ON COLUMN account_template.filters_json IS 'A JSON representation of any filters to be applied before returning report data. Each filter object should contain all of the following fields:\\ \&quot;field\&quot;: The column name\\ \&quot;operator\&quot;: The operator. Allowed operators: [\&quot;&#x3D;\&quot;, \&quot;!&#x3D;\&quot;, \&quot;in\&quot;, \&quot;not_in\&quot;, \&quot;~\&quot;, \&quot;&gt;\&quot;, \&quot;&lt;\&quot;, \&quot;contains_substring\&quot;]\\ \&quot;value\&quot;: A single value or a list of values';
COMMENT ON COLUMN account_template."id" IS 'Template ID';
COMMENT ON COLUMN account_template.ingestion_sources IS 'The filter on the conversion ingestion source method for conversion metrics';
COMMENT ON COLUMN account_template.is_default IS 'A boolean representing if this is the default view that loads for this template type';
COMMENT ON COLUMN account_template.is_deleted IS 'A boolean that indicates if the template has been deleted';
COMMENT ON COLUMN account_template.is_owned_by_user IS 'A boolean value that indicates if the user owns the template';
COMMENT ON COLUMN account_template.is_scheduled IS 'A boolean value that indicates if this template has been used to create a scheduled report';
COMMENT ON COLUMN account_template."name" IS 'Template Name';
COMMENT ON COLUMN account_template.report_end_relative_days_in_past IS 'The number of days prior to the day the report will be delivered at which the report will end';
COMMENT ON COLUMN account_template.report_start_relative_days_in_past IS 'The number of days prior to the day the report will be delivered at which the report will start';
COMMENT ON COLUMN account_template.reporting_time_zone IS 'Timezone for reporting data';
COMMENT ON COLUMN account_template.sort_by IS 'Unified metric sort configuration';
COMMENT ON COLUMN account_template."type" IS 'Type of the template';
COMMENT ON COLUMN account_template.updated_time IS 'Time of last update in seconds since Unix epoch';
COMMENT ON COLUMN account_template.user_id IS 'ID of the user who created the template';
COMMENT ON COLUMN account_template.view_window_days IS 'The length of the sliding window over which view conversions will be attributed';

--
-- Table 'ad' generated from model 'Ad'
--
CREATE TABLE IF NOT EXISTS ad (
    ad_account_id TEXT NOT NULL,
    ad_group_id TEXT NOT NULL,
    android_deep_link TEXT DEFAULT NULL,
    campaign_id TEXT NOT NULL,
    carousel_android_deep_links JSON DEFAULT NULL,
    carousel_destination_urls JSON DEFAULT NULL,
    carousel_ios_deep_links JSON DEFAULT NULL,
    carting_platform_type SMALLINT DEFAULT NULL,
    carting_products JSON DEFAULT NULL,
    click_tracking_url TEXT DEFAULT NULL,
    collection_items_destination_url_template TEXT DEFAULT NULL,
    collections_header_type TEXT DEFAULT NULL,
    created_time INTEGER DEFAULT NULL,
    creative_type TEXT NOT NULL,
    customizable_cta_type TEXT DEFAULT NULL,
    destination_url TEXT DEFAULT NULL,
    disclosure_type TEXT DEFAULT NULL,
    disclosure_url TEXT DEFAULT NULL,
    grid_click_type TEXT DEFAULT NULL,
    "id" VARCHAR(18) NOT NULL,
    ios_deep_link TEXT DEFAULT NULL,
    is_carting BOOLEAN DEFAULT NULL,
    is_collage_accepted_terms BOOLEAN DEFAULT NULL,
    is_collage_single_destination BOOLEAN DEFAULT NULL,
    is_pin_deleted BOOLEAN DEFAULT NULL,
    is_removable BOOLEAN DEFAULT NULL,
    lead_form_id TEXT DEFAULT NULL,
    "name" TEXT DEFAULT NULL,
    pin_id TEXT NOT NULL,
    quiz_pin_data TEXT DEFAULT NULL,
    rejected_reasons JSON NOT NULL,
    rejection_labels JSON NOT NULL,
    review_status TEXT NOT NULL,
    status TEXT DEFAULT NULL,
    summary_status TEXT NOT NULL,
    tracking_urls TEXT DEFAULT NULL,
    "type" TEXT NOT NULL,
    updated_time INTEGER DEFAULT NULL,
    view_tracking_url TEXT DEFAULT NULL
);
