    feed_profile_id TEXT DEFAULT NULL,
    "id" VARCHAR(18) NOT NULL,
    is_creative_optimization BOOLEAN DEFAULT NULL,
    is_local_inventory BOOLEAN DEFAULT NULL,
    lifetime_frequency_cap INTEGER DEFAULT NULL,
    local_inventory_radius_in_miles DECIMAL(20, 9) DEFAULT NULL,
    "name" TEXT NOT NULL,
    optimization_goal_metadata TEXT DEFAULT NULL,
    performance_plus_campaign_settings TEXT DEFAULT NULL,
    placement_group TEXT DEFAULT NULL,
    placement_traffic_type TEXT DEFAULT NULL,
    promotion_application_level TEXT DEFAULT NULL,
    promotion_id TEXT,
    promotion_ids JSON DEFAULT NULL,
    start_time INTEGER DEFAULT NULL,
    status TEXT DEFAULT NULL,
    summary_status TEXT NOT NULL,
    targeting_spec TEXT DEFAULT NULL,
    targeting_template_ids JSON DEFAULT NULL,
    tracking_urls TEXT DEFAULT NULL,
    "type" TEXT NOT NULL,
    updated_time INTEGER NOT NULL,
    auto_targeting_enabled BOOLEAN DEFAULT NULL,
    bid_multiplier DECIMAL(20, 9) DEFAULT NULL,
    budget_type TEXT DEFAULT NULL,
    pacing_delivery_type TEXT DEFAULT NULL
);
COMMENT ON TABLE ad_group IS 'Original model name - AdGroup.';
COMMENT ON COLUMN ad_group.ad_account_id IS 'Advertiser ID.';
COMMENT ON COLUMN ad_group.bid_in_micro_currency IS 'Bid price in micro currency. This field is **REQUIRED** for the following campaign objective_type/billable_event combinations: AWARENESS/IMPRESSION, CONSIDERATION/CLICKTHROUGH, CATALOG_SALES/CLICKTHROUGH, VIDEO_VIEW/VIDEO_V_50_MRC.';
COMMENT ON COLUMN ad_group.budget_in_micro_currency IS 'Budget in micro currency. This field is **REQUIRED** for non-CBO (campaign budget optimization) campaigns.  A CBO campaign automatically generates ad group budgets from its campaign budget to maximize campaign outcome. A CBO campaign is limited to 70 or less ad groups.';
COMMENT ON COLUMN ad_group.campaign_id IS 'Campaign ID of the ad group.';
COMMENT ON COLUMN ad_group.conversion_learning_mode_type IS 'oCPM learn mode';
COMMENT ON COLUMN ad_group.created_time IS 'Ad group creation time. Unix timestamp in seconds.';
COMMENT ON COLUMN ad_group.customer_segment_id IS 'Customer segment ID applied to the ad group. We currently only support 1 customer segment per ad group. To use customer segments, do not set the &#x60;targeting_template_ids&#x60; field as well as the &#x60;AUDIENCE_INCLUDE&#x60; field of the &#x60;targeting_spec&#x60;. To clear the customer segment ID, set this field to &#39;0&#39;.';
COMMENT ON COLUMN ad_group.dca_assets IS '[DCA] The Dynamic creative assets to use for DCA. Dynamic Creative Assembly (DCA) accepts basic creative assets of an ad (image, video, title, call to action, logo etc). Then it automatically generates optimized ad combinations based on these assets.';
COMMENT ON COLUMN ad_group.end_time IS 'Timestamp in Unix format for scheduling when ads in the ad group stop appearing. If not specified, ads run indefinitely unless you update the ad group by changing their status to &#x60;paused&#x60;. Cannot occur after &#x60;end_time&#x60; for parent campaign (if specified). Learn about [scheduling ads](https://help.pinterest.com/en/business/article/ads-manager-schedule-ads).  For certain organizations ([Closed beta](https://help.pinterest.com/en/business/article/beta-features)): Supported for campaigns with Campaign Budget Optimization (CBO).  For all organizations: Supported for campaigns without CBO.';
COMMENT ON COLUMN ad_group.feed_profile_id IS 'Feed Profile ID associated to the adgroup.';
COMMENT ON COLUMN ad_group."id" IS 'Ad group ID.';
COMMENT ON COLUMN ad_group.is_creative_optimization IS 'Enable creative optimization for the ad group, default value is FALSE. When enabled, you allow Pinterest to automatically turn your product Pins into ads in different formats (collections and shopping) and deliver those ads to users at scale.';
COMMENT ON COLUMN ad_group.is_local_inventory IS 'Indicates whether the ad group should use the local inventory.';
COMMENT ON COLUMN ad_group.lifetime_frequency_cap IS 'Set a limit to the number of times a promoted pin from this campaign can be impressed by a pinner within the past rolling 30 days. Only available for CPM (cost per mille (1000 impressions))  ad groups. A CPM ad group has an IMPRESSION [billable_event](https://help.pinterest.com/en/business/article/billable-events) value. This field **REQUIRES** the &#x60;end_time&#x60; field.';
COMMENT ON COLUMN ad_group.local_inventory_radius_in_miles IS 'The targeting radius of the local inventory ads in miles.';
COMMENT ON COLUMN ad_group."name" IS 'Ad group name.';
COMMENT ON COLUMN ad_group.optimization_goal_metadata IS 'Optimization goals for objective-based performance campaigns. **REQUIRED** when campaign&#39;s &#x60;objective_type&#x60; is set to &#x60;\&quot;WEB_CONVERSION\&quot;&#x60;.';
COMMENT ON COLUMN ad_group.performance_plus_campaign_settings IS 'Pinterest Performance+ campaign settings.';
COMMENT ON COLUMN ad_group.placement_group IS '[Placement group](https://help.pinterest.com/en/business/article/placement-groups).';
COMMENT ON COLUMN ad_group.placement_traffic_type IS 'A targeting option that enables advertisers to choose whether to run ads in fullscreen feed, two column feed, or both';
COMMENT ON COLUMN ad_group.promotion_application_level IS 'Specify if the promotion is applied at ad group or item level';
COMMENT ON COLUMN ad_group.promotion_id IS 'Promotion ID. To clear this field, set to null.';
COMMENT ON COLUMN ad_group.promotion_ids IS 'Promotion IDs list. To clear this field, set to an empty array [].';
COMMENT ON COLUMN ad_group.start_time IS 'Timestamp in Unix format for scheduling when ads in the ad group start to appear. If not specified, ads appear during parent campaign&#39;s &#x60;start_time&#x60;. Cannot precede &#x60;start_time&#x60; for parent campaign (if specified). Learn about [scheduling ads](/docs/api-features/managing-ads/#step-2-create-an-ad-group). For certain organizations ([Closed beta](/docs/getting-started/using-beta-and-restricted-features/)): Supported for campaigns with Campaign Budget Optimization (CBO). For all organizations: Supported for campaigns without CBO.';
COMMENT ON COLUMN ad_group.status IS 'Ad group/entity status.';
COMMENT ON COLUMN ad_group.targeting_template_ids IS 'Targeting template IDs applied to the ad group. We currently only support 1 targeting template per ad group. To use targeting templates, do not set any other targeting fields: targeting_spec, tracking_urls, auto_targeting_enabled, placement_group. To clear all targeting template IDs, set this field to [&#39;0&#39;].';
COMMENT ON COLUMN ad_group."type" IS 'Always \&quot;adgroup\&quot;.';
COMMENT ON COLUMN ad_group.updated_time IS 'Ad group last update time. Unix timestamp in seconds.';
COMMENT ON COLUMN ad_group.auto_targeting_enabled IS 'Enable auto-targeting for ad group. Default value is True. Also known as [\&quot;Performance+ targeting\&quot;](https://help.pinterest.com/en/business/article/performance-plus-targeting).';
COMMENT ON COLUMN ad_group.bid_multiplier IS '[Open beta](https://help.pinterest.com/en/business/article/beta-features) Bid multiplier for ad group. This value is a double between 0.1 and 10.0. Enter 0 to remove the bid multiplier. - Not currently supported for [Performance+ campaigns](https://help.pinterest.com/en/business/article/performance-plus-campaigns).';

